"""
Builds the Cumulus-style input message that starts the browse image workflow for a granule
"""
from regression.cmr import cmr_host
from regression.config import Deployment
from regression.manifest import RegressionCase

CMR_CLIENT_ID = 'POCLOUD'
OPERA_GRANULE_PROVIDER = 'opera'


def is_opera(short_name: str) -> bool:
    """True for OPERA collections, whose browse image is supplied with the granule instead of generated by Harmony."""
    return 'OPERA' in short_name


def build_input_message(case: RegressionCase, granule_cmr: dict, deployment: Deployment) -> dict:
    """
    Generate the workflow input message for a granule.

    Parameters
    ----------
    case : RegressionCase
        The test case being run
    granule_cmr : dict
        The granule's CMR search result item in UMM-JSON format
    deployment : Deployment
        The deployment the workflow runs in

    Returns
    -------
    dict
        A Cumulus message. For OPERA collections the granule also lists its browse GeoTIFF, expected to be
        staged in the deployment's private bucket.
    """
    meta = granule_cmr.get('meta', {})
    umm = granule_cmr.get('umm', {})

    concept_id = meta.get('concept-id', '')
    provider_id = meta.get('provider-id') or case.provider
    granule_id = umm.get('GranuleUR') or case.granule_ur
    collection_name = umm.get('CollectionReference', {}).get('ShortName') or case.short_name

    granule = {
        'granuleId': granule_id,
        'provider': provider_id,
        'cmrLink': f'https://{cmr_host(case.cmr_env)}/search/concepts/{concept_id}.umm_json',
        'cmrConceptId': concept_id
    }

    if is_opera(case.short_name):
        browse_filename = f'{granule_id}_BROWSE.tif'
        granule['provider'] = OPERA_GRANULE_PROVIDER
        granule['dataType'] = collection_name
        granule['files'] = [
            {
                'bucket': deployment.private_bucket,
                'fileName': browse_filename,
                'type': 'data',
                'key': f'{collection_name}/{browse_filename}',
                'source': f'{collection_name}/{granule_id}/{browse_filename}'
            }
        ]

    return {
        'cumulus_meta': {},
        'meta': {
            'buckets': {},
            'cmr': {
                'clientId': CMR_CLIENT_ID,
                'cmrEnvironment': case.cmr_env,
                'provider': provider_id
            },
            'collection': {
                'name': collection_name
            },
            'stack': deployment.resource_prefix,
            'provider': {}
        },
        'payload': {
            'granules': [granule]
        }
    }
